def resource_route(n):
    o=n['owner'];base=o.split('.')[0]
    if any(v in o for v in ['Tuning','tuning','Reward']):return 'GoogleGenAI.tunings.tune/get/list/cancel/validateReward, exact callable '+o
    if '$4' in base:return 'GoogleGenAI.batches.create inline request conversion, exact callable '+o
    if '$3' in base:return 'GoogleGenAI.caches.create content/tools conversion, exact callable '+o
    if '$2' in base or o.startswith(('live','Live','Session.')):return 'GoogleGenAI.live.connect or returned Session realtime/tool-response conversion, exact callable '+o
    if '$1' in base:return 'GoogleGenAI.models generation/count/embed conversion, exact callable '+o
    if any(v in o for v in ['Batch','batch','inlined','embeddingsBatch']):return 'GoogleGenAI.batches resource, exact callable '+o
    if any(v in o for v in ['Cached','cached','Caches']):return 'GoogleGenAI.caches resource, exact callable '+o
    if any(v in o for v in ['FileSearch','fileSearch','Document']):return 'GoogleGenAI.fileSearchStores or documents resource, exact callable '+o
    if o.startswith(('Files','NodeFiles','NodeUploader','NodeDownloader','upload','download')):return 'GoogleGenAI.files/fileSearchStores file API, exact callable '+o
    if o.startswith(('Tokens','createAuthToken','liveConnectConfigToMldev','liveConnectConstraints')):return 'GoogleGenAI.authTokens.create live token constraints, exact callable '+o
    return 'GoogleGenAI models/shared converter resource path, exact callable '+o

def route_for(n,role):
    o=n['owner']
    if role=='model':return dict(display='outgoing request/onPayload/direct converter/model context only',consumer=MODEL+' '+NATIVE)
    if role in ('debug','warning','console'):return dict(display='conditional console/process/debug publication; exact local guard/getter/callback required',consumer=LOG+' '+(AUTH if o.startswith('require_') else NEXT if o.startswith(('logRequest','logResponse','ClientSDK')) else API)+' '+NATIVE)
    if role=='auth-diagnostic':return dict(display='conditional Gaxios error.config/response redacted field API diagnostic',consumer=AUTH+' '+FLOW)
    if role=='auth':return dict(display='conditional selected private credential request rejection; optional native assistant error only if propagated',consumer=AUTH+' '+NATIVE+' '+FLOW)
    if role=='live' or 'node_modules/ws/' in o:return dict(display='optional Live callback/API error, default callback may suppress and connect may remain pending',consumer=LIVE)
    if role=='nextgen' or o.startswith(('ClientSDK','HTTPClient','GoogleGenAiDefaultError','pathToFunc','serverURLFromOptions','match','APIPromise')):return dict(display='optional NextGen SDK API rejection/debug data; no normal native generation invocation',consumer=NEXT)
